mapper.sql:
FROM system_users u
WHERE u.tenant_id = #{query.tenantId} AND u.status = 0 AND u.deleted = b'0'
  AND EXISTS (
    SELECT 1 FROM system_user_role ur JOIN system_role r ON r.id = ur.role_id
    WHERE ur.user_id = u.id AND ur.tenant_id = u.tenant_id AND ur.deleted = b'0'
      AND r.tenant_id = u.tenant_id AND r.code = #{query.roleCode} AND r.status = 0 AND r.deleted = b'0'
  )

  AND EXISTS (
    SELECT 1 FROM system_user_company_department_scope s
    JOIN system_company c ON c.id = s.company_id AND c.tenant_id = s.tenant_id
    WHERE s.tenant_id = u.tenant_id AND s.user_id = u.id AND s.company_id = #{query.companyId}
      AND s.deleted = b'0' AND s.status = 0 AND c.deleted = b'0' AND c.status = 0
      AND s.effective_from <= #{query.effectiveAt}
      AND (s.effective_to IS NULL OR s.effective_to > #{query.effectiveAt})
    AND s.scope_role = #{query.scopeRole}

      AND s.department_id = #{query.departmentId} AND s.department_code = #{query.departmentCode}
      AND EXISTS (SELECT 1 FROM system_dept d WHERE d.id = s.department_id
          AND d.tenant_id = u.tenant_id AND d.code = #{query.departmentCode} AND d.status = 0 AND d.deleted = b'0')

  )


    AND 1 = 0

        AND u.id IN #{id}



    AND (u.username LIKE CONCAT('%', #{query.keyword}, '%') OR u.nickname LIKE CONCAT('%', #{query.keyword}, '%'))
